                throw new ArgumentNullException(nameof(tONTransaction.TotalFees), "Property is required for class TONTransaction.");

            if (tONTransaction.TotalFeesExtraCurrenciesOption.IsSet && tONTransaction.TotalFeesExtraCurrencies == null)
                throw new ArgumentNullException(nameof(tONTransaction.TotalFeesExtraCurrencies), "Property is required for class TONTransaction.");

            if (tONTransaction.TraceIdOption.IsSet && tONTransaction.TraceId == null)
                throw new ArgumentNullException(nameof(tONTransaction.TraceId), "Property is required for class TONTransaction.");

            writer.WriteString("account", tONTransaction.Account);

            writer.WriteBoolean("isEmulated", tONTransaction.IsEmulated);

            writer.WriteString("logicalTime", tONTransaction.LogicalTime);

            writer.WriteNumber("mcBlockSeqno", tONTransaction.McBlockSeqno);

            writer.WriteNumber("now", tONTransaction.Now);

            writer.WritePropertyName("outMessages");
            JsonSerializer.Serialize(writer, tONTransaction.OutMessages, jsonSerializerOptions);
            if (tONTransaction.AccountStateAfterOption.IsSet)
            {
                writer.WritePropertyName("accountStateAfter");
                JsonSerializer.Serialize(writer, tONTransaction.AccountStateAfter, jsonSerializerOptions);
            }
            if (tONTransaction.AccountStateBeforeOption.IsSet)
            {
                writer.WritePropertyName("accountStateBefore");
                JsonSerializer.Serialize(writer, tONTransaction.AccountStateBefore, jsonSerializerOptions);
            }
            if (tONTransaction.BlockRefOption.IsSet)
            {
                writer.WritePropertyName("blockRef");
                JsonSerializer.Serialize(writer, tONTransaction.BlockRef, jsonSerializerOptions);
            }
            if (tONTransaction.DescriptionOption.IsSet)
            {
                writer.WritePropertyName("description");
                JsonSerializer.Serialize(writer, tONTransaction.Description, jsonSerializerOptions);
            }
            if (tONTransaction.EndStatusOption.IsSet)
            {
                var endStatusRawValue = TONAccountStatusValueConverter.ToJsonValue(tONTransaction.EndStatus.Value);
                writer.WriteString("endStatus", endStatusRawValue);
            }
            if (tONTransaction.InMessageOption.IsSet)
            {
                writer.WritePropertyName("inMessage");
                JsonSerializer.Serialize(writer, tONTransaction.InMessage, jsonSerializerOptions);
            }
            if (tONTransaction.OrigStatusOption.IsSet)
            {
                var origStatusRawValue = TONAccountStatusValueConverter.ToJsonValue(tONTransaction.OrigStatus.Value);
                writer.WriteString("origStatus", origStatusRawValue);
            }
            if (tONTransaction.PreviousTransactionHashOption.IsSet)
                writer.WriteString("previousTransactionHash", tONTransaction.PreviousTransactionHash);

            if (tONTransaction.PreviousTransactionLogicalTimeOption.IsSet)
                writer.WriteString("previousTransactionLogicalTime", tONTransaction.PreviousTransactionLogicalTime);

            if (tONTransaction.TotalFeesOption.IsSet)
                writer.WriteString("totalFees", tONTransaction.TotalFees);

            if (tONTransaction.TotalFeesExtraCurrenciesOption.IsSet)
            {
                writer.WritePropertyName("totalFeesExtraCurrencies");
                JsonSerializer.Serialize(writer, tONTransaction.TotalFeesExtraCurrencies, jsonSerializerOptions);
            }
            if (tONTransaction.TraceIdOption.IsSet)
                writer.WriteString("traceId", tONTransaction.TraceId);
        }
    }
